CREATE TABLE IF NOT EXISTS "user" (id uuid PRIMARY KEY, email VARCHAR(255) NOT NULL, username VARCHAR(255) NOT NULL, profile_image_url VARCHAR(500) NULL, is_email_verified BOOLEAN DEFAULT FALSE NOT NULL, is_onboarded BOOLEAN DEFAULT FALSE NOT NULL, confirm_over_eighteen BOOLEAN DEFAULT FALSE NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
ALTER TABLE "user" ADD CONSTRAINT user_email_unique UNIQUE (email);
ALTER TABLE "user" ADD CONSTRAINT user_username_unique UNIQUE (username);
CREATE TABLE IF NOT EXISTS auth_credential (id uuid PRIMARY KEY, user_id uuid NOT NULL, "type" INT NOT NULL, password_hash TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, provider_user_id TEXT NULL, CONSTRAINT fk_auth_credential_user_id__id FOREIGN KEY (user_id) REFERENCES "user"(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS exercise_group (id SERIAL PRIMARY KEY, "name" TEXT NOT NULL, description TEXT NULL);
CREATE TABLE IF NOT EXISTS payment (id uuid PRIMARY KEY, user_id uuid NULL, provider VARCHAR(32) NOT NULL, google_purchase_token VARCHAR(1024) NULL, google_order_id VARCHAR(500) NULL, apple_transaction_id VARCHAR(500) NULL, apple_original_transaction_id VARCHAR(500) NULL, stripe_payment_intent_id VARCHAR(500) NULL, stripe_checkout_session_id VARCHAR(500) NULL, paypal_order_id VARCHAR(500) NULL, paypal_capture_id VARCHAR(500) NULL, status VARCHAR(32) DEFAULT 'PENDING' NOT NULL, refunded_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
ALTER TABLE payment ADD CONSTRAINT payment_google_order_id_unique UNIQUE (google_order_id);
CREATE TABLE IF NOT EXISTS program_exercise (id uuid PRIMARY KEY, week_number INT NOT NULL, group_id INT NULL, title TEXT NOT NULL, description TEXT NULL, playback_id TEXT NULL, preview_playback_id TEXT NULL, thumbnail_url TEXT NULL, duration_seconds INT NULL, visibility INT DEFAULT 0 NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS refresh_token (id uuid PRIMARY KEY, replaced_by uuid NULL, user_id uuid NOT NULL, token_hash TEXT NOT NULL, issued_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, expires_at TIMESTAMP NOT NULL, revoked_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_refresh_token_user_id__id FOREIGN KEY (user_id) REFERENCES "user"(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS user_exercise_progress (id uuid PRIMARY KEY, user_id uuid NOT NULL, week INT NOT NULL, "day" INT NOT NULL, exercise_session INT NOT NULL, completed_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_user_exercise_progress_user_id__id FOREIGN KEY (user_id) REFERENCES "user"(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE user_exercise_progress ADD CONSTRAINT user_exercise_progress_user_id_week_day_exercise_session_unique UNIQUE (user_id, week, "day", exercise_session);
CREATE TABLE IF NOT EXISTS user_info_tics (id uuid PRIMARY KEY, user_id uuid NOT NULL, preferred_name VARCHAR(255) NULL, age INT NULL, stress_level INT NULL, tic_type INT NULL, tic_frequency INT NULL, tic_duration INT NULL, goal TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_user_info_tics_user_id__id FOREIGN KEY (user_id) REFERENCES "user"(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS user_program (id uuid PRIMARY KEY, user_id uuid NOT NULL, start_date DATE NOT NULL, end_date DATE NULL, timezone TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_user_program_user_id__id FOREIGN KEY (user_id) REFERENCES "user"(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS store_entitlement (id uuid PRIMARY KEY, store VARCHAR(16) NOT NULL, store_transaction_id VARCHAR(1024) NOT NULL, user_id uuid NULL, product_id VARCHAR(255) NULL, obfuscated_account_id VARCHAR(255) NULL, environment VARCHAR(32) NULL, revoked_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_store_entitlement_user_id__id FOREIGN KEY (user_id) REFERENCES "user"(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE store_entitlement ADD CONSTRAINT store_entitlement_store_store_transaction_id_unique UNIQUE (store, store_transaction_id);
ALTER TABLE store_entitlement ADD CONSTRAINT store_entitlement_store_user_id_unique UNIQUE (store, user_id);
CREATE SEQUENCE IF NOT EXISTS exercise_group_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;